JOIN addresses ad ON ad.street = 'ул. Тестовая' AND ad.house = 'Дом' AND ad.apartment = v.apartment
WHERE NOT EXISTS (SELECT 1 FROM water_meters m WHERE m.address_id = ad.id AND m.number = v.number);

