            ('138', '2628442', DATE '2026-09-20', 217.000)
        ) AS v(apartment, number, reading_date, value)
        JOIN addresses ad ON ad.street = 'ул. Тестовая' AND ad.house = 'Дом' AND ad.apartment = v.apartment
        JOIN water_meters m ON m.address_id = ad.id AND m.number = v.number
        WHERE NOT EXISTS (SELECT 1 FROM meter_readings x WHERE x.meter_id = m.id AND x.reading_date = v.reading_date)
        ORDER BY m.id, v.reading_date
    LOOP
        IF item.meter_id <> current_meter THEN
            current_meter := item.meter_id;
            previous := (SELECT id FROM meter_readings WHERE meter_id = item.meter_id ORDER BY reading_date DESC, id DESC LIMIT 1);
        END IF;
        INSERT INTO meter_readings (meter_id, value, reading_date, previous_reading_id, is_test)
        VALUES (item.meter_id, item.value, item.reading_date, previous, FALSE) RETURNING id INTO previous;
    END LOOP;
END $$;
